using Microsoft.Win32;

namespace TailShare;

/// <summary>Theme-specific .ico files in Assets\ (generated by scripts\make-icons.ps1).</summary>
internal static class AppIcons
{
    /// <summary>App mode ("Choose your default app mode"), which Explorer and app title bars follow.</summary>
    public static bool AppsUseLightTheme()
    {
        try
        {
            return Registry.GetValue(
                @"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize",
                "AppsUseLightTheme", 1) is not int value || value != 0;
        }
        catch
        {
            return true;
        }
    }

    /// <summary>Dark glyph for light backgrounds, white glyph for dark ones; null if the file is missing.</summary>
    public static string? IcoPath(bool lightTheme)
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Assets",
            lightTheme ? "TailShare-light.ico" : "TailShare-dark.ico");
        return File.Exists(path) ? path : null;
    }
}
